/**
 * Cross-language parity: app/js/field_guard.js must agree with the Python it was
 * ported from (ml/src/field_proximity.py + ml/src/field_policy.py) on every
 * golden vector.
 *
 * Two implementations of the same rules drift apart the moment one is edited,
 * and the one a blind user reads is the JS. The vectors are generated BY the
 * Python — ml/tests/test_field_guard_vectors.py, which also fails if the checked
 * -in table is stale — so there is exactly one reference here and this file only
 * compares. Nothing is re-implemented on the JS side to make a case pass.
 *
 * What "agree" means per vector type:
 *   validate   same ok AND the same reason string (the reason is spoken instead
 *              of the value, so a different reason is a different refusal)
 *   canonical  the same set of comparison tokens, in the same order
 *   resolve    the same field name and the same kind
 *   tokens     the same {field: value} map
 *   decide     the same decisions, in the same order: field, value, speak/refuse,
 *              why and source — order included, because it is what a caller reads
 *
 * Run:  node app/tools/field_guard_contract.js      (exit 0 = parity, 1 = not)
 */

"use strict";

const fs = require("fs");
const path = require("path");
const FG = require("../js/field_guard.js");

const FILE = path.resolve(__dirname, "field_guard_vectors.json");

// ── comparison ────────────────────────────────────────────────────────────────
//
// JSON objects have no order; JSON arrays do. `same` reflects that and nothing
// else, so a mismatch is always a real difference and never key order.

function same(a, b) {
  if (a === b) return true;
  if (a === null || b === null || a === undefined || b === undefined) return false;
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
    return a.every((x, i) => same(x, b[i]));
  }
  if (typeof a === "object" && typeof b === "object") {
    const ka = Object.keys(a).sort(), kb = Object.keys(b).sort();
    if (!same(ka, kb)) return false;
    return ka.every(k => same(a[k], b[k]));
  }
  return false;
}

const show = v => JSON.stringify(v);
const brief = v => {
  const s = show(v);
  return s.length > 300 ? s.slice(0, 300) + "..." : s;
};

// ── one vector ────────────────────────────────────────────────────────────────

function run(v) {
  switch (v.t) {
    case "validate": {
      const [ok, reason] = FG.validate(v.kind, v.value);
      return { got: { ok, reason }, want: { ok: v.ok, reason: v.reason } };
    }
    case "canonical":
      return { got: FG.canonical(v.kind, v.value), want: v.canon };
    case "resolve": {
      const [name, kind] = FG.resolveLabel(v.label);
      return { got: { name, kind }, want: { name: v.name, kind: v.kind } };
    }
    case "tokens":
      return { got: FG.fromRegexTokens(v.doc_type, v.tokens), want: v.out };
    case "decide": {
      const out = FG.decide(v.regex, v.spot, v.opts);
      // _i/_part are internal ordering keys: not part of the decision.
      const lean = out.map(d => ({ field: d.field, value: d.value,
                                   decision: d.decision, why: d.why, source: d.source }));
      return { got: lean, want: v.out };
    }
    default:
      return { got: null, want: null, error: `unknown vector type ${v.t}` };
  }
}

function label(v) {
  if (v.t === "validate") return `validate ${v.kind}(${show(v.value)})`;
  if (v.t === "canonical") return `canonical ${v.kind}(${show(v.value)})`;
  if (v.t === "resolve") return `resolve ${show(v.label)}`;
  if (v.t === "tokens") return `tokens ${show(v.doc_type)}`;
  const o = v.opts || {};
  return `decide doc_type=${show(o.doc_type)} strict=${o.strict_critical} ` +
         `free=${o.speak_free_text} regex=${brief(v.regex)} spot=${brief(v.spot)}`;
}

// ── run ───────────────────────────────────────────────────────────────────────

const payload = JSON.parse(fs.readFileSync(FILE, "utf8"));
const vectors = payload.vectors;

let pass = 0, fail = 0;
const byType = {};
for (const v of vectors) {
  byType[v.t] = byType[v.t] || { pass: 0, fail: 0 };
  let r;
  try {
    r = run(v);
  } catch (e) {
    r = { got: `<threw ${e && e.message}>`, want: v.out };
  }
  if (r.error) {
    r.got = r.error;
    r.want = "a known vector type";
  }
  if (same(r.got, r.want)) {
    pass++;
    byType[v.t].pass++;
  } else {
    fail++;
    byType[v.t].fail++;
    console.log(`FAIL  ${label(v)}`);
    console.log(`      python: ${brief(r.want)}`);
    console.log(`      js:     ${brief(r.got)}`);
  }
}

console.log("\nper-vector-type (python vs javascript):");
for (const t of Object.keys(byType).sort()) {
  const c = byType[t];
  console.log(`  ${t.padEnd(10)} ${String(c.pass).padStart(4)} passed` +
              `${c.fail ? "  " + c.fail + " FAILED" : ""}`);
}

console.log(`\nfield guard contract: ${vectors.length} vectors, ` +
            `${pass} passed, ${fail} FAILED`);
process.exit(fail ? 1 : 0);
